<?php
require_once __DIR__ . '/auth/auth_check.php';
require_once __DIR__ . '/config/database.php';

$stat = [
  'permohonan'=>(int)$pdo->query('SELECT COUNT(*) FROM permohonan')->fetchColumn(),
  'proses'=>(int)$pdo->query("SELECT COUNT(*) FROM permohonan WHERE status IN ('Diajukan','Dalam Pemeriksaan','Perlu Perbaikan')")->fetchColumn(),
  'selesai'=>(int)$pdo->query("SELECT COUNT(*) FROM permohonan WHERE status IN ('Disetujui','Selesai')")->fetchColumn(),
  'luas'=>(float)$pdo->query('SELECT COALESCE(SUM(luas_lahan),0) FROM rehabilitasi_das')->fetchColumn(),
];
$activity=$pdo->query('SELECT id,nomor_permohonan,tanggal_permohonan,nama_pemohon,jenis_permohonan,status FROM permohonan ORDER BY created_at DESC LIMIT 6')->fetchAll();
$yearRows=$pdo->query('SELECT YEAR(tanggal_permohonan) AS tahun,COUNT(*) AS jumlah FROM permohonan WHERE tanggal_permohonan>=DATE_SUB(CURDATE(),INTERVAL 4 YEAR) GROUP BY YEAR(tanggal_permohonan) ORDER BY tahun')->fetchAll();
$yearChart=['labels'=>array_column($yearRows,'tahun'),'values'=>array_map('intval',array_column($yearRows,'jumlah'))];
$statusRows=$pdo->query("SELECT status,COUNT(*) jumlah FROM permohonan GROUP BY status")->fetchAll();
$statusMap=[];foreach($statusRows as $row){$statusMap[$row['status']]=(int)$row['jumlah'];}
$chartCounts=[($statusMap['Diajukan']??0)+($statusMap['Dalam Pemeriksaan']??0)+($statusMap['Perlu Perbaikan']??0),($statusMap['Disetujui']??0)+($statusMap['Selesai']??0),$statusMap['Ditolak']??0];
?>
